/* From Uiverse.io by andrew-demchenk0 - Tags: button */
.__UIV_SCOPE__ button {
  position: relative;
  width: 130px;
  height: 35px;
  border-radius: 30px;
  background-color: white;
  border: 1px #000000 solid;
  overflow: hidden;
}

.__UIV_SCOPE__ .text1 {
  font-size: 17px;
  font-weight: 700;
  margin-left: 22%;
}

.__UIV_SCOPE__ .text2 {
  position: absolute;
  top: 25%;
  left: -50px;
  font-weight: 700;
  font-size: 14px;
  color: white;
}

.__UIV_SCOPE__ .icon {
  position: absolute;
  top: 0;
  left: 0;
  transition: transform 0.5s;
}

.__UIV_SCOPE__ .icon::before {
  position: absolute;
  left: -100px;
  top: 0;
  z-index: -1;
  content: '';
  width: 130px;
  height: 33px;
  border-radius: 30px;
  background-color: #000000;
}

.__UIV_SCOPE__ .icon::after {
  position: absolute;
  left: 0.5px;
  top: 0.5px;
  z-index: -1;
  content: '';
  width: 32px;
  height: 32px;
  border-radius: 100%;
  background-color: white;
}

.__UIV_SCOPE__ button:hover .icon {
  transform: translateX(97.5px);
  transition: transform 0.5s;
}

.__UIV_SCOPE__ button:hover .text2 {
  transform: translateX(100px);
  transition: transform 0.6s;
}

.__UIV_SCOPE__ button:active {
  transform: scale(1.03);
}
